UPDATE clinlims.menu SET parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_sample')
WHERE element_id IN ('menu_clinical_workflow', 'menu_environmental_workflow', 'menu_vector_workflow')
  AND parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_add_order');

UPDATE clinlims.menu SET is_active = false
WHERE element_id = 'menu_add_order' AND is_active = true;
